
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_hjs_b88_v2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_hjs_b88_v2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.260792072995095e+00, -4.179056146197692e+00, -4.064615004542615e+00, -3.906275032503777e+00, -3.690913027209168e+00, -3.405108896869448e+00, -3.038945236602734e+00, -2.592696581775916e+00, -2.085276971495413e+00, -1.556678311916079e+00, -1.038284019814281e+00, -6.508528892108808e-01, -5.435260415325130e-01, -4.429456636961174e-01, -3.115118933979207e-01, -1.873011902007930e-01, -9.668022162741305e-02, -4.053660710570522e-02, 0.000000000000000e+00, 0.000000000000000e+00]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


